"""A bounded memo of an expensive score."""


class Scorer:
    def __init__(self, f, limit=64):
        self.f = f
        self.limit = limit
        self._seen = {}

    def score(self, x):
        key = tuple(x)
        if key not in self._seen:
            v = self.f(key)
            if len(self._seen) >= self.limit:
                self._seen.clear()
            self._seen[key] = v
        return self._seen[key]

    def size(self):
        return len(self._seen)

"""A least-recently-used cache."""
from collections import OrderedDict


class LRU:
    def __init__(self, capacity):
        self.capacity = capacity
        self.d = OrderedDict()

    def get(self, k, default=None):
        if k not in self.d:
            return default
        self.d.move_to_end(k)
        return self.d[k]

    def put(self, k, v):
        if k in self.d:
            self.d.move_to_end(k)
        self.d[k] = v
        if len(self.d) > self.capacity:
            self.d.popitem(last=False)

    def keys(self):
        return list(self.d)

"""Values with a cached total and a cached maximum."""


class Stats:
    def __init__(self):
        self.values = []
        self._total = None
        self._top = None

    def add(self, v):
        self.values.append(v)
        self._total = None
        self._top = None

    def drop_last(self):
        v = self.values.pop()
        self._total = None
        self._top = None
        return v

    def total(self):
        if self._total is None:
            self._total = sum(self.values)
        return self._total

    def top(self):
        if self._top is None:
            self._top = max(self.values) if self.values else None
        return self._top

"""A sliding window that can be saved and restored."""


class Window:
    def __init__(self, size):
        self.size = size
        self.buf = []

    def push(self, x):
        self.buf.append(x)
        if len(self.buf) > self.size:
            self.buf.pop(0)

    def mean(self):
        return sum(self.buf) / len(self.buf) if self.buf else 0.0

    def state(self):
        return {'size': self.size, 'buf': list(self.buf)}

    @classmethod
    def load(cls, st):
        w = cls(st['size'])
        w.buf = list(st['buf'])
        return w

