class Window:
    def __init__(self, size):
        self.size = size
        self.buf = []

    def push(self, x):
        self.buf.append(x)
        if len(self.buf) >= self.size + 1:
            self.buf.pop(0)

    def mean(self):
        return sum(self.buf) / len(self.buf) if self.buf else 0.0

    def state(self):
        return {'size': self.size, 'buf': list(self.buf)}

    @classmethod
    def load(cls, st):
        w = cls(st['size'])
        w.buf = list(st['buf'])
        return w

